<template>
  <div class="hotspot">
    <div class="hotspot-top">
      <el-form ref="form" :model="paginationConfig" label-width="80px">
        <el-date-picker
          v-model="paginationConfig.analyzeTime"
          type="datetimerange"
          placeholder=""
          value-format="yyyy-MM-dd HH:mm:ss"
        ></el-date-picker>
        <el-button type="primary" @click="handleSearch">查询</el-button>
        <el-button type="primary" @click="handleResetFrom">重置</el-button>
      </el-form>
    </div>
    <div class="hotspot-content">
      <leafletMapComp ref="leafletMapComp"></leafletMapComp>
    </div>
  </div>
</template>

<script>
import { getHeatData } from "@/api/allRequset";
import leafletMapComp from "@/components/leafletMapComp/leafletMapComp.vue";

export default {
  name: "hotspotAnalysis",
  components: { leafletMapComp },
  mixins: [],
  props: {},
  computed: {},
  watch: {},
  filters: {},
  data() {
    return {
      formLabel: [
        {
          label: "时间区间",
          value: "analyzeTime",
          type: "datetimerange",
        },
      ],
      paginationConfig: {},
      customObj: {},
    };
  },
  methods: {
    handleSearch() {
      this.getMapData();
    },

    handleResetFrom() {
      this.paginationConfig = {};
      this.$refs.leafletMapComp
        .removeLayerByCustomObj(this.customObj)
        .then(() => {
          this.getMapData();
        })
        .catch((err) => {
          console.log(err, "err");
          this.getMapData();
        });
    },

    getMapData() {
      let { analyzeTime = [null, null], ...obj } = this.paginationConfig;
      let params = {
        ...obj,
        analyzeStartTime: analyzeTime[0],
        analyzeEndTime: analyzeTime[1],
      };
      getHeatData(params).then((res) => {
        console.log(res, "res");
        if (res.data.code === 1) {
          this.customObj = res.data.data;
          this.$refs.leafletMapComp.addHeatmapLayer({
            // res.data.data数据格式如下
            // let res = {
            //   "data": [
            //     {
            //       "lat": 37.009444567083655,
            //       "lng": 114.61056717194256,
            //       "count": 1.3
            //     },
            //     {
            //       "lat": 37.0407918812315,
            //       "lng": 114.18512965585427,
            //       "count": 1.2
            //     },
            //     {
            //       "lat": 36.98546428896102,
            //       "lng": 114.50018338398452,
            //       "count": 1.1
            //     },
            //     {
            //       "lat": 36.422523959450295,
            //       "lng": 115.61551957481066,
            //       "count": 0.5
            //     }
            //   ],
            //   "max": "2"
            // },

            data: res.data.data,
            customObj: this.customObj,
          });
        }
      });
    },
  },
  created() {
    this.getMapData();
  },
  mounted() {},
  destroyed() {},
};
</script>

